//! Keyboard layouts: what each key of the main block types, for the kernel
//! console and Slate's own programs alike (ADR 0039, ADR 0117).
//!
//! Keys are numbered as evdev numbers them, which for the main block is
//! also their scan code set 1 make code. Each key has four levels: plain,
//! Shift, AltGr (the right Alt key, in layouts that have one) and AltGr
//! with Shift. The tables (`layouts.rs`) are generated by `cargo xtask
//! keymaps` from xkeyboard-config's symbols files (MIT, the data ADR 0033
//! already takes key codes from). A level types a character or is a dead
//! key, which puts its accent on the next letter ([`Composer`], with the
//! Unicode Character Database's canonical compositions).

use crate::layouts::{COMPOSE, KEYS, LAYOUTS};

/// A keyboard layout (the installer records its name in
/// /etc/slate/keyboard).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Layout(u8);

impl Layout {
    /// English (US), the default.
    pub const US: Layout = Layout(0);

    /// Every layout, in the order of the installer's list.
    pub fn all() -> impl Iterator<Item = Layout> {
        (0..LAYOUTS.len() as u8).map(Layout)
    }

    /// The layout named as xkeyboard-config names it (`us`, `us(intl)`,
    /// `de`); None for one Slate doesn't have.
    pub fn by_name(name: &str) -> Option<Layout> {
        let name = match name.trim() {
            "uk" => "gb",
            n => n,
        };
        LAYOUTS.iter().position(|l| l.name == name).map(|i| Layout(i as u8))
    }

    /// The layout named, US for one Slate doesn't have.
    pub fn named(name: &str) -> Layout {
        Layout::by_name(name).unwrap_or_default()
    }

    pub fn name(self) -> &'static str {
        LAYOUTS[usize::from(self.0)].name
    }

    /// Its name for people: "German (Switzerland)".
    pub fn description(self) -> &'static str {
        LAYOUTS[usize::from(self.0)].description
    }

    /// Whether the right Alt key is AltGr (`level3(ralt_switch)`).
    pub fn has_altgr(self) -> bool {
        LAYOUTS[usize::from(self.0)].altgr
    }

    /// A number for it (to keep in an atomic), and back.
    pub fn code(self) -> u8 {
        self.0
    }

    pub fn from_code(code: u8) -> Option<Layout> {
        (usize::from(code) < LAYOUTS.len()).then_some(Layout(code))
    }
}

/// The 102nd key, between left Shift and Z on ISO keyboards (`<LSGT>`).
pub const KEY_102ND: u16 = 86;

/// What a key's level is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Sym {
    Char(char),
    /// A dead key: the combining mark it puts on the next letter
    /// (U+0301 COMBINING ACUTE ACCENT for an acute).
    Dead(char),
}

impl Sym {
    fn from_raw(v: u32) -> Option<Sym> {
        match v {
            0 => None,
            v if v & (1 << 31) != 0 => char::from_u32(v & !(1 << 31)).map(Sym::Dead),
            v => char::from_u32(v).map(Sym::Char),
        }
    }
}

/// The four levels of `code` (plain, Shift, AltGr, AltGr and Shift).
pub fn levels(layout: Layout, code: u16) -> Option<[Option<Sym>; 4]> {
    let i = KEYS.iter().position(|&k| k == code)?;
    Some(LAYOUTS[usize::from(layout.0)].keys[i].map(Sym::from_raw))
}

/// What `code` is with the modifiers given: Caps Lock shifts the letters
/// whose Shift level is their capital (on both level pairs).
pub fn key(layout: Layout, code: u16, shift: bool, caps: bool, altgr: bool) -> Option<Sym> {
    let l = levels(layout, code)?;
    let (plain, shifted) = if altgr && layout.has_altgr() { (l[2], l[3]) } else { (l[0], l[1]) };
    let letter = match (plain, shifted) {
        (Some(Sym::Char(a)), Some(Sym::Char(b))) => a.is_alphabetic() && a != b && a.to_uppercase().eq([b]),
        _ => false,
    };
    if shift != (caps && letter) { shifted } else { plain }
}

/// The character `code` types with the modifiers given, if it types one
/// by itself (not a dead key).
pub fn character(layout: Layout, code: u16, shift: bool, caps: bool, altgr: bool) -> Option<char> {
    match key(layout, code, shift, caps, altgr)? {
        Sym::Char(c) => Some(c),
        Sym::Dead(_) => None,
    }
}

/// The character `base` with the combining `mark` on it, if Unicode has
/// one (a canonical composition).
pub fn compose(mark: char, base: char) -> Option<char> {
    let (m, b) = (u16::try_from(u32::from(mark)).ok()?, u16::try_from(u32::from(base)).ok()?);
    let i = COMPOSE.binary_search_by(|e| (e.0, e.1).cmp(&(m, b))).ok()?;
    char::from_u32(u32::from(COMPOSE[i].2))
}

/// A dead key's accent by itself (the spacing character people expect
/// after the dead key and Space).
pub fn spacing(mark: char) -> char {
    match mark {
        '\u{300}' => '`',
        '\u{301}' => '´',
        '\u{302}' => '^',
        '\u{303}' | '\u{342}' => '~',
        '\u{304}' => '¯',
        '\u{306}' => '˘',
        '\u{307}' => '˙',
        '\u{308}' => '¨',
        '\u{30A}' => '˚',
        '\u{30B}' => '˝',
        '\u{30C}' => 'ˇ',
        '\u{327}' => '¸',
        '\u{328}' => '˛',
        '\u{331}' => 'ˍ',
        // Marks with no spacing form of their own: the mark alone.
        m => m,
    }
}

/// What a key typed after the dead keys before it: up to two characters.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Typed {
    chars: [Option<char>; 2],
}

impl Typed {
    fn one(c: char) -> Typed {
        Typed { chars: [Some(c), None] }
    }

    pub fn chars(self) -> impl Iterator<Item = char> {
        self.chars.into_iter().flatten()
    }

    pub fn is_empty(self) -> bool {
        self.chars[0].is_none()
    }
}

/// Dead keys (ADR 0117): one waits for the next key, which gets its
/// accent if Unicode has the letter (` ´ ` then `e` is `é`); Space, or
/// the same dead key again, types the accent by itself; anything else
/// types the accent and then itself.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Composer {
    pending: Option<char>,
}

impl Composer {
    pub const fn new() -> Composer {
        Composer { pending: None }
    }

    /// Whether a dead key is waiting.
    pub fn pending(&self) -> bool {
        self.pending.is_some()
    }

    /// Forget a waiting dead key (a key that types nothing came, like
    /// Enter or an arrow).
    pub fn reset(&mut self) {
        self.pending = None;
    }

    /// What `sym` types now.
    pub fn feed(&mut self, sym: Sym) -> Typed {
        match (self.pending.take(), sym) {
            (None, Sym::Char(c)) => Typed::one(c),
            (None, Sym::Dead(m)) => {
                self.pending = Some(m);
                Typed::default()
            }
            (Some(p), Sym::Char(' ')) => Typed::one(spacing(p)),
            (Some(p), Sym::Char(c)) => match compose(p, c) {
                Some(x) => Typed::one(x),
                None => Typed { chars: [Some(spacing(p)), Some(c)] },
            },
            (Some(p), Sym::Dead(m)) if m == p => Typed::one(spacing(p)),
            (Some(p), Sym::Dead(m)) => Typed { chars: [Some(spacing(p)), Some(spacing(m))] },
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn l(name: &str) -> Layout {
        Layout::by_name(name).unwrap()
    }

    #[test]
    fn us_and_gb() {
        let (us, gb) = (Layout::US, l("gb"));
        assert_eq!(us.name(), "us");
        assert_eq!(character(us, 3, true, false, false), Some('@'));
        assert_eq!(character(gb, 3, true, false, false), Some('"'));
        assert_eq!(character(gb, 4, true, false, false), Some('£'));
        assert_eq!(character(us, 16, false, true, false), Some('Q'));
        assert_eq!(character(us, 2, false, true, false), Some('1'));
        assert_eq!(character(gb, KEY_102ND, false, false, false), Some('\\'));
        assert_eq!(character(us, KEY_102ND, true, false, false), Some('>'));
        assert_eq!(character(us, 57, false, false, false), Some(' '));
        assert_eq!(Layout::by_name("uk"), Some(gb));
        assert_eq!(Layout::by_name("xx"), None);
        assert_eq!(Layout::from_code(gb.code()), Some(gb));
    }

    #[test]
    fn altgr() {
        let gb = l("gb");
        assert_eq!(character(gb, 5, false, false, true), Some('€'));
        assert_eq!(character(gb, 30, false, false, true), Some('æ'));
        assert_eq!(character(gb, 30, true, false, true), Some('Æ'));
        assert_eq!(character(gb, 30, false, true, true), Some('Æ'));
        // A dead key types nothing by itself; US has no AltGr.
        assert_eq!(character(gb, 26, false, false, true), None);
        assert_eq!(key(gb, 26, false, false, true), Some(Sym::Dead('\u{308}')));
        assert_eq!(character(Layout::US, 5, false, false, true), Some('4'));
        assert!(!Layout::US.has_altgr());
    }

    /// Layouts as xkeyboard-config has them.
    #[test]
    fn more_layouts() {
        let (de, fr, intl) = (l("de"), l("fr"), l("us(intl)"));
        assert_eq!(de.description(), "German");
        // QWERTZ, the umlauts, AltGr's @ and €.
        assert_eq!(character(de, 21, false, false, false), Some('z'));
        assert_eq!(character(de, 44, false, false, false), Some('y'));
        assert_eq!(character(de, 40, true, false, false), Some('Ä'));
        assert_eq!(character(de, 40, false, true, false), Some('Ä'));
        assert_eq!(character(de, 16, false, false, true), Some('@'));
        assert_eq!(character(de, 18, false, false, true), Some('€'));
        assert_eq!(key(de, 13, false, false, false), Some(Sym::Dead('\u{301}')));
        // AZERTY: Shift for the digits, Caps Lock leaves them.
        assert_eq!(character(fr, 16, false, false, false), Some('a'));
        assert_eq!(character(fr, 3, false, false, false), Some('é'));
        assert_eq!(character(fr, 3, true, false, false), Some('2'));
        assert_eq!(character(fr, 3, false, true, false), Some('é'));
        assert_eq!(key(fr, 26, false, false, false), Some(Sym::Dead('\u{302}')));
        // US international: ' is dead, AltGr's is not.
        assert_eq!(key(intl, 40, false, false, false), Some(Sym::Dead('\u{301}')));
        assert_eq!(character(intl, 40, false, false, true), Some('\''));
        assert!(Layout::all().count() >= 16);
        assert!(Layout::all().all(|l| character(l, 57, false, false, false) == Some(' ')));
    }

    #[test]
    fn dead_keys() {
        let acute = Sym::Dead('\u{301}');
        let mut c = Composer::new();
        assert!(c.feed(acute).is_empty());
        assert!(c.pending());
        assert_eq!(c.feed(Sym::Char('e')).chars().collect::<std::vec::Vec<_>>(), ['é']);
        assert!(!c.pending());
        c.feed(Sym::Dead('\u{302}'));
        assert_eq!(c.feed(Sym::Char('A')).chars().collect::<std::vec::Vec<_>>(), ['Â']);
        c.feed(Sym::Dead('\u{308}'));
        assert_eq!(c.feed(Sym::Char('u')).chars().collect::<std::vec::Vec<_>>(), ['ü']);
        // Space, or the dead key twice: the accent; no such letter: both.
        c.feed(acute);
        assert_eq!(c.feed(Sym::Char(' ')).chars().collect::<std::vec::Vec<_>>(), ['´']);
        c.feed(Sym::Dead('\u{302}'));
        assert_eq!(c.feed(Sym::Dead('\u{302}')).chars().collect::<std::vec::Vec<_>>(), ['^']);
        c.feed(acute);
        assert_eq!(c.feed(Sym::Char('q')).chars().collect::<std::vec::Vec<_>>(), ['´', 'q']);
        c.feed(Sym::Dead('\u{327}'));
        assert_eq!(c.feed(Sym::Char('c')).chars().collect::<std::vec::Vec<_>>(), ['ç']);
        c.feed(acute);
        c.reset();
        assert_eq!(c.feed(Sym::Char('e')).chars().collect::<std::vec::Vec<_>>(), ['e']);
        assert_eq!(compose('\u{30C}', 's'), Some('š'));
        assert_eq!(compose('\u{328}', 'a'), Some('ą'));
        assert_eq!(compose('\u{301}', '1'), None);
    }
}
